inputs.value:
@if(
  equals(coalesce(variables('varStartTicks'), 0), 0),
  0,
  max(
    div(
      sub(
        ticks(
          coalesce(
            variables('varCompletedAtUtc'),
            utcNow()
          )
        ),
        variables('varStartTicks')
      ),
      10000
    ),
    0
  )
)

Compose_Task_Acknowledgement_Link.inputs:
@concat(
  'https://taskack.page.gd/index.html',
  '?item=',
  string(coalesce(outputs('Get_item_Task')?['body/ID'], 0)),
  '&name=',
  uriComponent(
    first(
      split(
        trim(replace(replace(string(coalesce(outputs('Get_item_Task')?['body/AssignedTo'], '')), decodeUriComponent('%0A'), ''), decodeUriComponent('%0D'), '')),
        '@'
      )
    )
  ),
  '&email=',
  uriComponent(
    trim(replace(replace(string(coalesce(outputs('Get_item_Task')?['body/AssignedTo'], '')), decodeUriComponent('%0A'), ''), decodeUriComponent('%0D'), ''))
  ),
  '&title=',
  uriComponent(
    trim(replace(replace(string(coalesce(outputs('Get_item_Task')?['body/Title'], '')), decodeUriComponent('%0A'), ' '), decodeUriComponent('%0D'), ' '))
  ),
  '&ref=',
  uriComponent(
    concat('TASK-', string(coalesce(outputs('Get_item_Task')?['body/ID'], 0)))
  )
)

